function playgroundView(){
 const lang=state.playgroundLanguage||'html';
 const code=state.playgroundCodes?.[lang]??(state.playgroundLanguage===lang?state.playgroundCode:null)??playgroundStarters[lang];
 const browserLang=['html','css','javascript'].includes(lang);
 return `${pageHead('YOUR CREATIVE WORKSPACE','Code playground','Write code, provide input when needed, run it, and inspect the real output.')}
 <div class="playground-shell">
  <div class="playground-toolbar"><div class="playground-toolbar-copy"><span class="live-dot"></span><strong>Multi-language coding lab</strong><small>HTML · CSS · JavaScript · Python · C · C++ · Java</small></div>
   <div class="toolbar"><select id="playLanguage" class="field" aria-label="Choose programming language"><option value="html" ${lang==='html'?'selected':''}>HTML</option><option value="css" ${lang==='css'?'selected':''}>CSS</option><option value="javascript" ${lang==='javascript'?'selected':''}>JavaScript</option><option value="python" ${lang==='python'?'selected':''}>Python 3</option><option value="c" ${lang==='c'?'selected':''}>C</option><option value="cpp" ${lang==='cpp'?'selected':''}>C++</option><option value="java" ${lang==='java'?'selected':''}>Java</option></select><button class="button secondary" id="resetCode">↺ Reset</button><button class="button secondary" id="savePlayground">Save code</button><button class="button primary" id="runCode">▶ Run code</button></div>
  </div>
  <div class="playground-grid">
   <section class="editor-panel playground-editor-panel"><div class="editor-tabs"><span class="editor-tab active" id="activeLanguageLabel">${lang.toUpperCase()} · main</span><span class="editor-language">CODE EDITOR</span></div><div class="editor-stack"><textarea id="polyCode" class="editor code-pane active" spellcheck="false" aria-label="Code editor">${esc(code)}</textarea></div><div class="editor-foot"><span id="languageHint">${browserLang?'Runs in a sandboxed browser preview':'Runs with a language runtime / online compiler'}</span><span>Code autosaves while you type</span></div>
    <div class="program-input-wrap" id="programInputWrap" ${browserLang?'hidden':''}><label for="programInput">Program input (optional)</label><textarea id="programInput" class="field" rows="4" placeholder="Enter input for input(), scanf(), cin or Scanner here. Use one line per input."></textarea></div>
   </section>
   <section class="preview-panel"><div class="preview-head"><div><span class="preview-live-dot"></span><strong id="outputTitle">${lang==='html'||lang==='css'?'Live preview':lang==='javascript'?'Web preview + console':'Program output'}</strong></div><span id="previewStatus">READY</span></div>
    <iframe id="previewFrame" class="preview" sandbox="allow-scripts allow-modals" title="Sandboxed web preview" ${browserLang?'':'hidden'}></iframe>
    <pre id="programOutput" class="program-output" ${lang==='html'||lang==='css'?'hidden':''}>Run your program to see its output here.</pre>
    <div class="preview-foot"><span>Output / preview</span><span>Errors are shown here too</span></div>
   </section>
  </div>
  <p class="playground-safety">HTML, CSS and JavaScript run in a sandboxed browser preview. Python uses Pyodide in your browser. C, C++ and Java need the secure Cloudflare Pages compiler backend plus the ONLINECOMPILER_API_KEY secret; they will not execute on a static GitHub Pages deployment. For Java, keep the public class name as Main. Do not enter passwords, API keys or personal data into this demo playground.</p>
 </div>`;
}

