function formatCompilerOutput(result){
 const compile=result?.compile||{},run=result?.run||{};
 const parts=[];
 const compileError=String(compile.stderr||'').trim();
 const compileOutput=String(compile.output||'').trim();
 const stdout=String(run.stdout||'').replace(/\s+$/,'');
 const stderr=String(run.stderr||'').trim();
 if(compileError)parts.push('COMPILER ERRORS:\n'+compileError);
 if(compileOutput)parts.push('COMPILER OUTPUT:\n'+compileOutput);
 if(stdout)parts.push(stdout);
 if(stderr)parts.push((compile.code!==undefined||compileError?'COMPILER / RUNTIME ERRORS:\n':'PROGRAM ERRORS:\n')+stderr);
 // Some compatible services return only `output` rather than stdout/stderr.
 const combined=String(run.output||'').trim();
 if(!stdout&&!stderr&&combined)parts.push(combined);
 if(!parts.length){
  if(result?.message)parts.push(String(result.message));
  else if(run.message)parts.push(String(run.message));
  else if(compile.code!==undefined&&compile.code!==0)parts.push('Compilation failed (exit code '+compile.code+').');
  else if(run.code!==undefined&&run.code!==0)parts.push('Program exited with code '+run.code+'.');
  else parts.push('Program finished successfully with no printed output.');
 }
 if(compile.code!==undefined&&compile.code!==0)parts.push('Compilation exit code: '+compile.code);
 if(run.code!==undefined&&run.code!==0)parts.push('Program exit code: '+run.code);
 if(run.status)parts.push('Execution status: '+run.status);
 return parts.join('\n\n');
}
async function runCode(){
 const files=getPlaygroundFiles(),lang=files.language,code=files.code,frame=$('#previewFrame'),out=$('#programOutput');
 if(!code.trim()){showProgramOutput('Write some code first, then click Run code.');setRunStatus('EMPTY');return;}
 const runId=(window.__codeMagicRunId||0)+1;window.__codeMagicRunId=runId;
 const input=$('#programInput')?.value||'';
 const runButton=$('#runCode');if(runButton)runButton.disabled=true;
 if(out){out.hidden=true;out.textContent='';}
 if(frame)frame.hidden=true;
 setRunStatus('RUNNING…');
 try{
  if(lang==='html'){
   showPreview(code);setRunStatus('PREVIEW');return;
  }
  if(lang==='css'){
   const safeCss=code.replace(/<\/style/gi,'<\\/style');
   const sample='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>'+safeCss+'</style></head><body><main class="card"><h1>CSS preview</h1><p>This sample page lets you test your CSS selectors, layout, colors, spacing and responsive rules.</p><button type="button">Example button</button><ul><li>First item</li><li>Second item</li></ul><input placeholder="Example input"></main></body></html>';
   showPreview(sample);setRunStatus('PREVIEW');return;
  }
  if(lang==='javascript'){
   const safeCode=code.replace(/<\/script/gi,'<\\/script');
   const bridge=`<script>
    const __cmSend=(kind,args)=>{let text=args.map(v=>{try{return typeof v==='string'?v:JSON.stringify(v);}catch(e){return String(v);}}).join(' ');parent.postMessage({type:'codemagic-console',runId:${runId},kind,text},'*');};
    ['log','info','warn','error','debug','table'].forEach(k=>console[k]=(...a)=>__cmSend(k,a));
    window.addEventListener('error',e=>__cmSend('error',[e.message+' ('+e.filename+':'+e.lineno+')']));
    window.addEventListener('unhandledrejection',e=>__cmSend('error',['Unhandled promise rejection:',e.reason?.stack||e.reason]));
   <\/script>`;
   const jsPage='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{font:15px Arial,sans-serif;padding:18px;color:#20243a}#app{min-height:70px;padding:12px;border:1px dashed #c8cde0;border-radius:10px}button{padding:8px 12px;margin:4px}</style></head><body><h2>JavaScript preview</h2><div id="app">Your JavaScript can update this page using document.querySelector("#app").</div>'+bridge+'<script>try{\n'+safeCode+'\n}catch(e){console.error(e.stack||e);}<\/script></body></html>';
   if(frame)frame.onload=()=>{if(runId===window.__codeMagicRunId)setRunStatus('FINISHED');};
   showPreview(jsPage,{consoleVisible:true,consoleText:'JavaScript console is ready. Output and errors will appear here.'});setRunStatus('RUNNING IN BROWSER');return;
  }
  if(lang==='python'){
   showProgramOutput('Loading Python runtime…');setRunStatus('LOADING PYTHON');
   if(!window.loadPyodide){
    if(!window.__codeMagicPyodideScript){window.__codeMagicPyodideScript=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/pyodide/v0.27.7/full/pyodide.js';script.onload=resolve;script.onerror=()=>{window.__codeMagicPyodideScript=null;reject(new Error('Could not download Python runtime. Check your internet connection or try again.'));};document.head.appendChild(script);});}
    await window.__codeMagicPyodideScript;
   }
   window.codeMagicPyodide=window.codeMagicPyodide||await loadPyodide();
   // Pyodide raw stdio callbacks provide one byte at a time. Decode the byte
   // stream so non-ASCII output (including Bangla) is not corrupted.
   let output='';
   const stdoutDecoder=new TextDecoder('utf-8');
   const stderrDecoder=new TextDecoder('utf-8');
   window.codeMagicPyodide.setStdout({raw:byte=>{output+=stdoutDecoder.decode(new Uint8Array([byte]),{stream:true});}});
   window.codeMagicPyodide.setStderr({raw:byte=>{output+=stderrDecoder.decode(new Uint8Array([byte]),{stream:true});}});
   // stdin is a byte stream, not a JavaScript character stream. Encoding it
   // first also makes input() work correctly with Unicode text.
   const inputBytes=new TextEncoder().encode(input.replace(/\r\n/g,'\n'));
   let inputIndex=0;
   window.codeMagicPyodide.setStdin({stdin:()=>inputIndex<inputBytes.length?inputBytes[inputIndex++]:null});
   await window.codeMagicPyodide.runPythonAsync(code);
   output+=stdoutDecoder.decode();
   output+=stderrDecoder.decode();
   if(runId!==window.__codeMagicRunId)return;
   showProgramOutput(output||'Program finished successfully with no printed output.');setRunStatus('FINISHED');return;
  }
  const configs={c:{language:'c',filename:'main.c'},cpp:{language:'c++',filename:'main.cpp'},java:{language:'java',filename:'Main.java'}};
  const config=configs[lang];if(!config)throw new Error('Unsupported language: '+lang);
  showProgramOutput('Sending code to the secure online compiler…');
  const controller=new AbortController();
  const timeout=setTimeout(()=>controller.abort(),45000);
  let response;
  try{
   response=await fetch(new URL('/api/run-code',window.location.origin),{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({language:config.language,filename:config.filename,code,stdin:input})});
  }finally{clearTimeout(timeout);}
  let result={};try{result=await response.json();}catch(e){}
  if(!response.ok){const detail=result.error||result.message;if(response.status===404)throw new Error('The compiler backend was not found. If this site is hosted on GitHub Pages, C, C++ and Java cannot run there. Deploy this project to Cloudflare Pages and add the ONLINECOMPILER_API_KEY secret.');throw new Error(detail||('Code runner returned HTTP '+response.status+'.'));}
  if(runId!==window.__codeMagicRunId)return;
  showProgramOutput(formatCompilerOutput(result));
  const compileFailed=result.compile&&result.compile.code!==0;
  const runFailed=result.run&&result.run.code!==0;
  const runStatus=result.run?.status;
  setRunStatus(compileFailed?'COMPILE ERROR':runStatus==='TO'?'TIMEOUT':runStatus==='OL'?'OUTPUT LIMIT':runFailed?'ERROR':(!result.run&&result.message)?'ERROR':'FINISHED');
 }catch(err){
  if(runId!==window.__codeMagicRunId)return;
  const message=err.name==='AbortError'?'The online compiler took too long and the request timed out. Try a smaller program.':(err.message||String(err));
  showProgramOutput(message+'\n\nCheck your internet connection. Online execution also depends on the compiler service being available.');setRunStatus('ERROR');
 }finally{if(runId===window.__codeMagicRunId&&runButton)runButton.disabled=false;}
}
function changePlaygroundLanguage(lang){
 // The select already contains the NEW language when its change event fires.
 // Save the editor text against the PREVIOUS language before loading the new starter/code.
 const previousLang=state.playgroundLanguage||'html';
 const previousCode=$('#polyCode')?.value??state.playgroundCode??playgroundStarters[previousLang];
 state.playgroundCodes=state.playgroundCodes||{};state.playgroundCodes[previousLang]=previousCode;
 state.playgroundLanguage=lang;state.playgroundCode=state.playgroundCodes[lang]??playgroundStarters[lang];save();
 const editor=$('#polyCode');if(editor)editor.value=state.playgroundCode;
 const label=$('#activeLanguageLabel');if(label)label.textContent=lang.toUpperCase()+' · main';
 const browserLang=['html','css','javascript'].includes(lang);
 const hint=$('#languageHint');if(hint)hint.textContent=browserLang?'Runs in a sandboxed browser preview':'Runs with a language runtime / online compiler';
 const frame=$('#previewFrame'),out=$('#programOutput');if(frame)frame.hidden=!browserLang;if(out)out.hidden=lang==='html'||lang==='css';
 const inputWrap=$('#programInputWrap');if(inputWrap)inputWrap.hidden=browserLang;
 const title=$('#outputTitle');if(title)title.textContent=lang==='html'||lang==='css'?'Live preview':lang==='javascript'?'Web preview + console':'Program output';
 if(out)out.textContent='Run your program to see its output here.';
 setRunStatus('READY');
}

